  const key=JSON.stringify([q,c,l]);if(!refresh&&(radioPending.current===key||(radioLoaded.current.key===key&&Date.now()-radioLoaded.current.at<300000)))return;
  const id=++radioSerial.current;radioController.current?.abort();const controller=new AbortController();radioController.current=controller;radioPending.current=key;
  setRadioData((old:any)=>({...old,loading:true}));
  try{const result=await request(`/api/radio?q=${encodeURIComponent(q)}&country=${encodeURIComponent(c)}&language=${encodeURIComponent(l)}`,{signal:controller.signal});if(id!==radioSerial.current)return;
   if(result?.error){if(activePage.current==='radio')setErr(result.error);radioLoaded.current={key:'',at:0};}else{radioLoaded.current={key,at:Date.now()};setErr(old=>old==='radio_catalog_unavailable'?'':old);}
   setRadioData({...result,loading:false});
  }catch(e:any){if(id!==radioSerial.current||controller.signal.aborted)return;if(activePage.current==='radio')setErr(e.name==='TimeoutError'?'radio_catalog_unavailable':e.message);setRadioData((old:any)=>({...old,loading:false,error:'radio_catalog_unavailable'}));}
