 const searchGeo=async(q:string)=>{const id=++geoSerial.current;setGeo([]);if(!q.trim()){setGeoStatus('idle');return;}setGeoStatus('loading');try{const result=await request(`/api/geocode?q=${encodeURIComponent(q)}`);if(id!==geoSerial.current)return;const results=result.results||[];setGeo(results);setGeoStatus(results.length?'idle':'empty');}catch(e:any){if(id!==geoSerial.current)return;setGeoStatus('idle');setErr(e.message);}};
